// src/resources/surface.ts
var SURFACE_ITEM_CAP = 200;
registerResourceModule({
  name: "guardian-surface-latest",
  uri: "guardian://surface/latest",
  description: `Latest attack-surface snapshot of the server's working-directory project, from \`map_attack_surface\`: routes (code- and spec-provenance) with resolved path, method, params and auth hint, env vars, declared ports, per-language coverage, spec_files and the spec_diff (matched, code_only, spec_only, unmatchable). Each list is capped at ${SURFACE_ITEM_CAP} entries \u2014 \`totals\` has the true counts, \`truncated\` names what was cut, and guardian://surface/{snapshot_id} returns the whole snapshot. Import edges and third-party imports are counted, not inlined. Returns \`{ snapshot: null }\` when none exists yet.`,
  handler: async (_uri, _params, ctx) => {
    const latest = ctx.storage.surface.getLatestForProject(serverProjectPath());
    if (!latest) return { json: { snapshot: null } };
    const { snapshot, totals, truncated } = boundSnapshot(latest.snapshot);
    return {
      json: {
        snapshot_id: latest.id,
        captured_at: latest.captured_at,
        snapshot,
        totals,
        truncated,
        ...truncated.length > 0 ? { full_snapshot: `guardian://surface/${latest.id}` } : {}
      }
    };
  }
});
registerResourceModule({
  name: "guardian-surface-by-id",
  uri: "guardian://surface/{id}",
  isTemplate: true,
  description: "A specific attack-surface snapshot by id, as returned in `snapshot_id` by `map_attack_surface`, in full. Returns `{ snapshot: null }` for an unknown id.",
  handler: async (_uri, params, ctx) => {
    const rawId = Array.isArray(params["id"]) ? params["id"][0] : params["id"];
    const id = Number.parseInt(String(rawId ?? ""), 10);
    if (Number.isNaN(id)) return { json: { snapshot: null } };
    const found = ctx.storage.surface.getById(id);
    if (!found) return { json: { snapshot: null } };
    return {
      json: {
        snapshot_id: found.id,
        captured_at: found.captured_at,
        snapshot: found.snapshot
      }
    };
  }
});
function boundSnapshot(s) {
  const truncated = [];
  const list2 = (items) => Array.isArray(items) ? items : [];
  const cap = (name, items) => {
    const all = list2(items);
    if (all.length > SURFACE_ITEM_CAP) truncated.push(name);
    return all.slice(0, SURFACE_ITEM_CAP);
  };
  const { imports, external_imports, spec_diff, ...rest } = s;
  const diff = spec_diff ?? null;
  const snapshot = {
    ...rest,
    routes: cap("routes", s.routes),
    webhooks: cap("webhooks", s.webhooks),
    env_vars: cap("env_vars", s.env_vars),
    ports: cap("ports", s.ports),
    spec_files: cap("spec_files", s.spec_files),
    spec_diff: diff === null ? null : {
      ...diff,
      matched: cap("spec_diff.matched", diff.matched),
      code_only: cap("spec_diff.code_only", diff.code_only),
      spec_only: cap("spec_diff.spec_only", diff.spec_only),
      unmatchable: cap("spec_diff.unmatchable", diff.unmatchable)
    }
  };
  const totals = {
    routes: list2(s.routes).length,
    webhooks: list2(s.webhooks).length,
    env_vars: list2(s.env_vars).length,
    ports: list2(s.ports).length,
    spec_files: list2(s.spec_files).length,
    imports: list2(imports).length,
    // (file, package) pairs, capped lists included at their true count.
    // Null, not 0, for a snapshot mapped before they were recorded.
    external_imports: external_imports === void 0 ? null : list2(external_imports.packages).reduce((sum, p) => sum + p.file_count, 0),
    ...diff === null ? {} : {
      spec_diff: {
        matched: list2(diff.matched).length,
        code_only: list2(diff.code_only).length,
        spec_only: list2(diff.spec_only).length,
        unmatchable: list2(diff.unmatchable).length
      }
    }
  };
  return { snapshot, totals, truncated };
}

// src/server.ts
var SERVER_NAME = "dev-guardian";
var SERVER_VERSION2 = resolveVersion();
async function main() {
  if (!nodeSqliteAvailable()) {
    process.stderr.write(`${NODE_SQLITE_REQUIRED}
`);
    process.exit(1);
  }
  const projectPath = resolve23(process.cwd());
  const { db, path: dbPath, warning: storageWarning } = openDatabase({ projectPath });
  const storage = new Storage(db);
  logErr(`db opened: ${dbPath}`);
  if (storageWarning) logErr(`db warning: ${storageWarning}`);
  reapOrphanedScans(storage, logErr);
  const shell = await probeShell(storage.runtimeMeta);
  if (shell === null) {
    logErr(
      "no usable bash found \u2014 script-invoking tools will return no_bash_shell. Install Git Bash or WSL, then restart."
    );
  } else {
    logErr(`shell: ${shell.label}`);
  }
  const guard = ensureGuardianIgnored(projectPath);
  if (guard.updated) logErr(`.gitignore ${guard.reason} for .guardian/`);
  const mcp = new McpServer({ name: SERVER_NAME, version: SERVER_VERSION2 });
  const progressNotifier = {
    send: (payload) => {
      void mcp.server.notification({
        method: "notifications/progress",
        params: { ...payload }
      });
    }
  };
  const ctx = {
    storage,
    shell,
    scriptsDir: resolveScriptsDir(),
    progressNotifier,
    ...storageWarning ? { storageWarning } : {}
  };
  attachAllTools(mcp, ctx);
  attachAllResources(mcp, ctx);
  logErr(`registered ${TOOLS.length} tool(s), ${RESOURCES.length} resource(s)`);
  const background = { cancel: () => {
  } };
  installShutdownHooks(mcp, storage, background);
  await mcp.connect(new StdioServerTransport());
  logErr("listening on stdio");
  background.cancel = scheduleRetention(storage, logErr);
}
function installShutdownHooks(mcp, storage, background) {
  let closing = false;
  const shutdown = (reason, closeTransport) => {
    if (closing) return;
    closing = true;
    logErr(`${reason}; shutting down`);
    background.cancel();
    try {
      storage.close();
    } catch {
    }
    if (!closeTransport) process.exit(0);
    void mcp.close().finally(() => {
      process.exit(0);
    });
  };
  process.on("SIGINT", () => shutdown("received SIGINT", true));
  process.on("SIGTERM", () => shutdown("received SIGTERM", true));
  process.stdout.on("error", (error2) => {
    if (error2.code === "EPIPE") {
      shutdown("stdout closed by the client (EPIPE)", false);
      return;
    }
    logErr(`fatal: stdout: ${error2.stack ?? error2.message}`);
    process.exit(1);
  });
  process.stderr.on("error", () => {
  });
}
function logErr(line) {
  process.stderr.write(`[dev-guardian] ${line}
`);
}
main().catch((err) => {
  logErr(`fatal: ${err instanceof Error ? err.stack ?? err.message : String(err)}`);
  process.exit(1);
});
